<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Controle de Despesas</title>
<link rel="stylesheet" href="/styles.css" />
</head>
<body>
<header>
  <h1>💰 Controle de Despesas</h1>
</header>

<div class="container">
  <div class="centerbox card">
    <h2>Entrar</h2>
    <div id="tabs" class="tabs">
      <button id="tabLogin" class="active">Entrar</button>
      <button id="tabRegister">Criar conta</button>
    </div>

    <div id="loginBox">
      <label>E-mail</label>
      <input id="loginEmail" type="email" />
      <div style="height:8px"></div>
      <label>Senha</label>
      <input id="loginPassword" type="password" />
      <div style="height:12px"></div>
      <button id="btnLogin" style="width:100%">Entrar</button>
      <div id="loginError" class="error"></div>
    </div>

    <div id="registerBox" class="hidden">
      <label>Nome</label>
      <input id="regName" />
      <div style="height:8px"></div>
      <label>E-mail</label>
      <input id="regEmail" type="email" />
      <div style="height:8px"></div>
      <label>Senha (mínimo 6 caracteres)</label>
      <input id="regPassword" type="password" />
      <div style="height:12px"></div>
      <button id="btnRegister" style="width:100%">Criar conta</button>
      <div id="regError" class="error"></div>
    </div>
  </div>
</div>

<script>
const tabLogin = document.getElementById('tabLogin');
const tabRegister = document.getElementById('tabRegister');
const loginBox = document.getElementById('loginBox');
const registerBox = document.getElementById('registerBox');

tabLogin.onclick = () => {
  tabLogin.classList.add('active');
  tabRegister.classList.remove('active');
  loginBox.classList.remove('hidden');
  registerBox.classList.add('hidden');
};
tabRegister.onclick = () => {
  tabRegister.classList.add('active');
  tabLogin.classList.remove('active');
  registerBox.classList.remove('hidden');
  loginBox.classList.add('hidden');
};

async function post(url, data) {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });
  const json = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(json.error || 'Erro');
  return json;
}

document.getElementById('btnLogin').onclick = async () => {
  const err = document.getElementById('loginError');
  err.textContent = '';
  try {
    const user = await post('/api/login', {
      email: document.getElementById('loginEmail').value.trim(),
      password: document.getElementById('loginPassword').value
    });
    window.location.href = user.role === 'admin' ? '/admin' : '/app';
  } catch (e) {
    err.textContent = e.message;
  }
};

document.getElementById('btnRegister').onclick = async () => {
  const err = document.getElementById('regError');
  err.textContent = '';
  try {
    await post('/api/register', {
      name: document.getElementById('regName').value.trim(),
      email: document.getElementById('regEmail').value.trim(),
      password: document.getElementById('regPassword').value
    });
    window.location.href = '/app';
  } catch (e) {
    err.textContent = e.message;
  }
};

// Se já estiver logado, vai direto
fetch('/api/me').then(r => r.ok ? r.json() : null).then(u => {
  if (u) window.location.href = u.role === 'admin' ? '/admin' : '/app';
});
</script>
</body>
</html>


