<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Meus Gastos</title>
<link rel="stylesheet" href="/styles.css" />
</head>
<body>
<header>
  <h1>💰 Meus Gastos</h1>
  <nav>
    <span id="who" style="opacity:.85;font-size:14px"></span>
    <a id="logout">Sair</a>
  </nav>
</header>

<div class="container">
  <div class="grid grid-2">
    <div class="card">
      <h2>Registrar gasto</h2>
      <label>Valor (R$)</label>
      <input id="expAmount" type="number" step="0.01" min="0.01" />
      <div style="height:8px"></div>
      <label>Descrição</label>
      <input id="expDesc" placeholder="Ex: Almoço no restaurante" />
      <div style="height:8px"></div>
      <label>Categoria</label>
      <select id="expCategory"></select>
      <div style="height:8px"></div>
      <label>Data</label>
      <input id="expDate" type="date" />
      <div style="height:12px"></div>
      <button id="btnAdd" style="width:100%">Adicionar gasto</button>
      <div id="addMsg" class="error"></div>
    </div>

    <div class="card">
      <h2>Resumo</h2>
      <div class="grid grid-2">
        <div class="stat">
          <div class="value" id="totalMonth">R$ 0,00</div>
          <div class="label">Gasto no mês atual</div>
        </div>
        <div class="stat">
          <div class="value" id="totalAll">R$ 0,00</div>
          <div class="label">Total geral</div>
        </div>
      </div>
      <div style="height:16px"></div>
      <h3 style="font-size:14px;margin:0 0 8px 0">Por categoria</h3>
      <div id="catList" class="muted">Sem dados ainda.</div>
    </div>
  </div>

  <div class="card">
    <h2>Meus gastos</h2>
    <table>
      <thead>
        <tr>
          <th>Data</th>
          <th>Descrição</th>
          <th>Categoria</th>
          <th style="text-align:right">Valor</th>
          <th></th>
        </tr>
      </thead>
      <tbody id="expTbody"></tbody>
    </table>
  </div>
</div>

<script>
let categories = [];

async function api(url, opts) {
  const r = await fetch(url, opts);
  const json = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(json.error || 'Erro');
  return json;
}

function money(v) {
  return 'R$ ' + Number(v).toFixed(2).replace('.', ',');
}

function todayISO() {
  const d = new Date();
  return d.toISOString().slice(0, 10);
}

async function init() {
  try {
    const me = await api('/api/me');
    document.getElementById('who').textContent = me.name;
    if (me.role === 'admin') {
      const a = document.createElement('a');
      a.href = '/admin';
      a.textContent = 'Painel Admin';
      document.querySelector('header nav').insertBefore(a, document.getElementById('logout'));
    }
  } catch (e) {
    window.location.href = '/';
    return;
  }

  document.getElementById('expDate').value = todayISO();

  categories = await api('/api/categories');
  const sel = document.getElementById('expCategory');
  sel.innerHTML = '<option value="">Selecione...</option>';
  categories.filter(c => c.active).forEach(c => {
    const o = document.createElement('option');
    o.value = c.id;
    o.textContent = c.name;
    sel.appendChild(o);
  });

  await refresh();
}

function catName(id) {
  const c = categories.find(x => x.id === id);
  return c ? c.name : '—';
}

async function refresh() {
  const expenses = await api('/api/expenses');
  const tbody = document.getElementById('expTbody');
  tbody.innerHTML = '';
  if (expenses.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" class="muted">Nenhum gasto registrado.</td></tr>';
  }
  for (const e of expenses) {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${e.date.split('-').reverse().join('/')}</td>
      <td>${e.description || '—'}</td>
      <td>${catName(e.categoryId)}</td>
      <td style="text-align:right">${money(e.amount)}</td>
      <td style="text-align:right"><button class="danger small" data-id="${e.id}">Excluir</button></td>
    `;
    tr.querySelector('button').onclick = async () => {
      if (!confirm('Excluir este gasto?')) return;
      await api('/api/expenses/' + e.id, { method: 'DELETE' });
      refresh();
    };
    tbody.appendChild(tr);
  }

  const s = await api('/api/summary');
  document.getElementById('totalMonth').textContent = money(s.totalMonth);
  document.getElementById('totalAll').textContent = money(s.totalAll);

  const catList = document.getElementById('catList');
  const withValues = s.byCategory.filter(c => c.total > 0).sort((a, b) => b.total - a.total);
  if (withValues.length === 0) {
    catList.innerHTML = '<div class="muted">Sem dados ainda.</div>';
  } else {
    const max = withValues[0].total;
    catList.innerHTML = withValues.map(c => `
      <div style="margin-bottom:10px">
        <div style="display:flex;justify-content:space-between;font-size:14px">
          <span>${c.name}</span>
          <strong>${money(c.total)}</strong>
        </div>
        <div class="bar"><div style="width:${(c.total / max * 100).toFixed(1)}%"></div></div>
      </div>
    `).join('');
  }
}

document.getElementById('btnAdd').onclick = async () => {
  const msg = document.getElementById('addMsg');
  msg.textContent = '';
  try {
    await api('/api/expenses', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        amount: document.getElementById('expAmount').value,
        description: document.getElementById('expDesc').value,
        categoryId: document.getElementById('expCategory').value,
        date: document.getElementById('expDate').value
      })
    });
    document.getElementById('expAmount').value = '';
    document.getElementById('expDesc').value = '';
    refresh();
  } catch (e) {
    msg.textContent = e.message;
  }
};

document.getElementById('logout').onclick = async () => {
  await fetch('/api/logout', { method: 'POST' });
  window.location.href = '/';
};

init();
</script>
</body>
</html>


